INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Backup-Strategien nur für große Unternehmen nötig?', 2, '[{"text": "Nein", "correct": true, "because": "Alle Daten sollten gesichert werden"}, {"text": "Ja", "correct": false, "because": "Auch kleine Firmen profitieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Backup-Strategien?', 3, '[{"text": "Datensicherung", "correct": true, "because": "Schutz vor Datenverlust"}, {"text": "Datenmenge maximieren", "correct": false, "because": "Nicht primär"}, {"text": "Schnelle Verarbeitung", "correct": false, "because": "Sicherheit im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu Backup-Strategien?', 5, '[{"text": "Regelmäßige Sicherungen", "correct": true, "because": "Schützt aktuelle Daten"}, {"text": "Wiederherstellungspläne", "correct": true, "because": "Stellt Daten wieder her"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Backups schützen vor Datenverlust. b) Sie sind nur für Hardware-Fehler nötig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Softwarefehler und Angriffe"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei Backup-Strategien?', 4, '[{"text": "Sicherungshäufigkeit", "correct": false, "because": "Wichtig für Schutz"}, {"text": "Wiederherstellbarkeit", "correct": false, "because": "Kern der Strategie"}, {"text": "Visuelles Design", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Backups auch vor Ransomware schützen?', 2, '[{"text": "Ja", "correct": true, "because": "Wiederherstellung möglich"}, {"text": "Nein", "correct": false, "because": "Effektiver Schutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode ist typisch für Backups?', 3, '[{"text": "Inkrementelle Sicherung", "correct": true, "because": "Effizient bei Änderungen"}, {"text": "Hohe Serverleistung", "correct": false, "because": "Irrelevant"}, {"text": "Statische IPs", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ansätze gehören zu Backup-Strategien?', 5, '[{"text": "Vollbackup", "correct": true, "because": "Komplette Datensicherung"}, {"text": "Offsite-Speicherung", "correct": true, "because": "Schutz vor physischen Schäden"}, {"text": "Maximale Speichergröße", "correct": false, "because": "Nicht vorgeschrieben"}, {"text": "Animationseffekte", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Backups sichern Verfügbarkeit. b) Sie sind nur einmalig nötig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Regelmäßigkeit erforderlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Backup-Strategien?', 4, '[{"text": "Sicherungsplan", "correct": false, "because": "Definiert Häufigkeit"}, {"text": "Testwiederherstellung", "correct": false, "because": "Sichert Funktionalität"}, {"text": "Grafikdesign", "correct": true, "because": "Kein Sicherheitsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Backups nur für Hardware-Fehler?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Software und Angriffe"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Strategien sichern Daten effektiv?', 4, '[{"text": "3-2-1-Regel", "correct": true, "because": "Mehrere Kopien, verschiedene Medien"}, {"text": "Cloud-Backup", "correct": true, "because": "Externer Speicher"}, {"text": "Visuelles Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Backups automatisch sicher sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Testen der Wiederherstellung nötig"}, {"text": "Ja", "correct": false, "because": "Überprüfung erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Backup-Strategien?', 3, '[{"text": "Wiederherstellbarkeit", "correct": true, "because": "Sichert Verfügbarkeit"}, {"text": "Schnelle Übertragung", "correct": false, "because": "Sekundär"}, {"text": "Schriftarten", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Regelmäßige Backups sind essenziell. b) Ein Backup reicht immer aus.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Mehrere Kopien nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden verbessern Backup-Strategien?', 5, '[{"text": "Differenzielle Sicherung", "correct": true, "because": "Spart Zeit bei Änderungen"}, {"text": "Verschlüsselung", "correct": true, "because": "Schützt Backup-Daten"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Schutzfaktor"}, {"text": "Unsortierte Daten", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Backup-Strategien unwichtig?', 3, '[{"text": "Speicherort", "correct": false, "because": "Schützt vor Verlust"}, {"text": "Wiederherstellungsplan", "correct": false, "because": "Sichert Funktionalität"}, {"text": "Animationseffekte", "correct": true, "because": "Kein Sicherheitsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Schützen Backups auch vor physischen Schäden?', 3, '[{"text": "Ja", "correct": true, "because": "Mit Offsite-Backups"}, {"text": "Nein", "correct": false, "because": "Externer Speicher hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Backups getestet werden sollten?', 2, '[{"text": "Ja", "correct": true, "because": "Sichert Wiederherstellbarkeit"}, {"text": "Nein", "correct": false, "because": "Tests sind nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip wähle ich für eine Backup-Strategie?', 4, '[{"text": "3-2-1-Regel", "correct": true, "because": "Mehrere Kopien, verschiedene Orte"}, {"text": "Maximale Speichergröße", "correct": false, "because": "Irrelevant"}, {"text": "Grafisches Design", "correct": false, "because": "Kein Schutzfokus"}]');
